mkdir -p src spec test
cat > src/node-machine.ts <<'EOF'
// The stateful core of a consensus node: a pure transition function.

export type Role = 'follower' | 'candidate' | 'leader' | 'shutdown';
export interface NodeState { role: Role; term: number }

export const MAX_TERM = 3;
export const INITIAL_STATE: NodeState = { role: 'follower', term: 0 };

export type Command =
  | { type: 'electionTimeout' }
  | { type: 'electionWon' }
  | { type: 'newerTermSeen'; term: number }
  | { type: 'quorumLost' }
  | { type: 'shutdown' };

export type Step = { ok: true; state: NodeState } | { ok: false; reason: string };

export function step(s: NodeState, c: Command): Step {
  if (s.role === 'shutdown') return { ok: false, reason: 'node is shut down' };
  switch (c.type) {
    case 'electionTimeout':
      if (s.role === 'leader') return { ok: false, reason: 'the leader does not time out' };
      if (s.term >= MAX_TERM) return { ok: false, reason: `no term after ${MAX_TERM}` };
      return { ok: true, state: { role: 'candidate', term: s.term + 1 } };
    case 'electionWon':
      if (s.role !== 'candidate') return { ok: false, reason: 'only a candidate can win an election' };
      return { ok: true, state: { role: 'leader', term: s.term } };
    case 'newerTermSeen': {
      const t = c.term;
      if (typeof t !== 'number' || !Number.isInteger(t) || t < 1 || t > MAX_TERM) {
        return { ok: false, reason: `term must be an integer from 1 to ${MAX_TERM}` };
      }
      if (t <= s.term) return { ok: false, reason: 'term is not newer' };
      return { ok: true, state: { role: 'follower', term: t } };
    }
    case 'quorumLost':
      if (s.role !== 'leader') return { ok: false, reason: 'only the leader can lose its quorum' };
      return { ok: true, state: { role: 'follower', term: s.term } };
    case 'shutdown':
      return { ok: true, state: { role: 'shutdown', term: s.term } };
    default:
      return { ok: false, reason: 'unknown command' };
  }
}
EOF
cat > src/host.impl.ts <<'EOF'
import type { CreateHost, Host, NodeView, Outcome } from '../host.ts';
import { INITIAL_STATE, step } from './node-machine.ts';
import type { Command, NodeState } from './node-machine.ts';

const createHost: CreateHost = async () => {
  let state: NodeState = { ...INITIAL_STATE };
  const apply = async (c: Command): Promise<Outcome> => {
    const r = step(state, c);
    if (!r.ok) return { ok: false, reason: r.reason };
    state = r.state;
    return { ok: true };
  };
  const host: Host = {
    electionTimeout: () => apply({ type: 'electionTimeout' }),
    electionWon: () => apply({ type: 'electionWon' }),
    newerTermSeen: (term: number) => apply({ type: 'newerTermSeen', term }),
    quorumLost: () => apply({ type: 'quorumLost' }),
    shutdown: () => apply({ type: 'shutdown' }),
    node: async (): Promise<NodeView> => ({ role: state.role, term: state.term }),
  };
  return host;
};

export default createHost;
EOF
cat > tsconfig.json <<'EOF'
{ "compilerOptions": { "target": "es2022", "module": "nodenext", "moduleResolution": "nodenext", "strict": true, "noEmit": true, "allowImportingTsExtensions": true, "verbatimModuleSyntax": true, "erasableSyntaxOnly": true }, "include": ["host.ts", "src", "test"] }
EOF
cat > test/host.test.ts <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('starts a follower in term 0', async () => {
  const h = await createHost();
  assert.deepEqual(await h.node(), { role: 'follower', term: 0 });
});

test('election path and step-down', async () => {
  const h = await createHost();
  assert.equal((await h.electionWon()).ok, false);
  assert.equal((await h.quorumLost()).ok, false);
  assert.deepEqual(await h.electionTimeout(), { ok: true });
  assert.deepEqual(await h.node(), { role: 'candidate', term: 1 });
  assert.deepEqual(await h.electionTimeout(), { ok: true });
  assert.deepEqual(await h.node(), { role: 'candidate', term: 2 });
  assert.deepEqual(await h.electionWon(), { ok: true });
  assert.deepEqual(await h.node(), { role: 'leader', term: 2 });
  assert.equal((await h.electionTimeout()).ok, false);
  assert.equal((await h.electionWon()).ok, false);
  assert.deepEqual(await h.quorumLost(), { ok: true });
  assert.deepEqual(await h.node(), { role: 'follower', term: 2 });
});

test('term caps at 3', async () => {
  const h = await createHost();
  for (let i = 0; i < 3; i++) assert.equal((await h.electionTimeout()).ok, true);
  const r = await h.electionTimeout();
  assert.equal(r.ok, false);
  assert.equal(typeof (r as any).reason, 'string');
  assert.deepEqual(await h.node(), { role: 'candidate', term: 3 });
});

test('newerTermSeen', async () => {
  const h = await createHost();
  for (const bad of [0, 4, -1, 1.5, NaN]) assert.equal((await h.newerTermSeen(bad)).ok, false);
  await h.electionTimeout(); await h.electionWon();
  assert.equal((await h.newerTermSeen(1)).ok, false);
  assert.deepEqual(await h.newerTermSeen(3), { ok: true });
  assert.deepEqual(await h.node(), { role: 'follower', term: 3 });
  assert.equal((await h.newerTermSeen(3)).ok, false);
});

test('shutdown is final and keeps the term', async () => {
  const h = await createHost();
  await h.electionTimeout();
  assert.deepEqual(await h.shutdown(), { ok: true });
  assert.deepEqual(await h.node(), { role: 'shutdown', term: 1 });
  for (const r of [await h.shutdown(), await h.electionTimeout(), await h.electionWon(), await h.newerTermSeen(2), await h.quorumLost()]) assert.equal(r.ok, false);
  assert.deepEqual(await h.node(), { role: 'shutdown', term: 1 });
});

test('fresh systems are independent', async () => {
  const a = await createHost(); await a.electionTimeout();
  const b = await createHost();
  assert.deepEqual(await b.node(), { role: 'follower', term: 0 });
});
EOF
