  await h.electionTimeout();
  await h.electionWon();
  assert.equal((await h.newerTermSeen(1)).ok, false);
  assert.deepEqual(await h.newerTermSeen(3), { ok: true });
  assert.deepEqual(await h.node(), { role: 'follower', term: 3 });
  assert.equal((await h.newerTermSeen(3)).ok, false);
});

test('shutdown is final and keeps the term', async () => {
  const h = await createHost();
  await h.electionTimeout();
  assert.deepEqual(await h.shutdown(), { ok: true });
  assert.deepEqual(await h.node(), { role: 'shutdown', term: 1 });
  const rs = [await h.shutdown(), await h.electionTimeout(), await h.electionWon(), await h.newerTermSeen(2), await h.quorumLost()];
  for (const r of rs) assert.equal(r.ok, false);
  assert.deepEqual(await h.node(), { role: 'shutdown', term: 1 });
});

test('fresh systems are independent', async () => {
  const a = await createHost();
  await a.electionTimeout();
  const b = await createHost();
  assert.deepEqual(await b.node(), { role: 'follower', term: 0 });
});

