// The rules the brief requires, as polygraph invariants.
const ROLES = ['follower', 'candidate', 'leader', 'shutdown'];
const same = (a, b) => a.role === b.role && a.term === b.term;

export const stateInvariants = [
  { name: 'role is one of the four', pred: (s) => ROLES.includes(s.role) },
  { name: 'term is an integer in 0..3', pred: (s) => Number.isInteger(s.term) && s.term >= 0 && s.term <= 3 },
  { name: 'term 0 means follower or shutdown (no election yet)', pred: (s) => s.term > 0 || s.role === 'follower' || s.role === 'shutdown' },
];

export const transitionInvariants = [
  { name: 'term never goes down', pred: (pre, a, d, post) => post.term >= pre.term },
  {
    name: 'only an election or a newer term changes the term',
    pred: (pre, a, d, post) => post.term === pre.term || a === 'electionTimeout' || a === 'newerTermSeen',
  },
  {
    name: 'election moves the term up by exactly 1 into candidate',
    pred: (pre, a, d, post) => a !== 'electionTimeout' || same(pre, post) || (post.role === 'candidate' && post.term === pre.term + 1),
  },
  {
    name: 'a leader was a candidate first in its own term',
    pred: (pre, a, d, post) => post.role !== 'leader' || pre.role === 'leader' || (pre.role === 'candidate' && pre.term === post.term),
  },
  { name: 'a leader never times out', pred: (pre, a, d, post) => !(a === 'electionTimeout' && pre.role === 'leader') || same(pre, post) },
  { name: 'a shut down node stays shut down, unchanged', pred: (pre, a, d, post) => pre.role !== 'shutdown' || same(pre, post) },
  { name: 'shutdown keeps the term', pred: (pre, a, d, post) => post.role !== 'shutdown' || post.term === pre.term },
  {
    name: 'newerTermSeen only accepts a strictly newer term in 1..3 and makes a follower',
    pred: (pre, a, d, post) =>
      a !== 'newerTermSeen' || same(pre, post) ||
      (post.role === 'follower' && post.term === d.term && Number.isInteger(d.term) && d.term >= 1 && d.term <= 3 && d.term > pre.term),
  },
  {
    name: 'quorumLost: leader steps down in the same term',
    pred: (pre, a, d, post) => a !== 'quorumLost' || same(pre, post) || (pre.role === 'leader' && post.role === 'follower' && post.term === pre.term),
  },
];

