'use strict';
// SAM v2 strict-profile spec of src/node-machine.ts (step).

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const MAX_TERM = 3;
const PEERS = ['n1', 'n2'];
// role: 'follower' | 'candidate' | 'leader' | 'shutdown'
// votedFor: 'nobody' | 'itself' | 'n1' | 'n2' (the vote in the current term)
const INITIAL_STATE = { role: 'follower', term: 0, votedFor: 'nobody' };

const TERMS = [-1, 0, 1, 1.5, 2, 3, 4];
const CANDIDATES = ['n1', 'n2', 'n3', 'itself', 'nobody'];

const noData = () => ({ action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] });
const validTerm = (t) => typeof t === 'number' && Number.isInteger(t) && t >= 1 && t <= MAX_TERM;

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      role: { type: 'string' },
      term: { type: 'number' },
      votedFor: { type: 'string' },
    },
    actions: {
      electionTimeout: noData(),
      electionWon: noData(),
      newerTermSeen: {
