// The rules the brief requires, as polygraph invariants.
const ROLES = ['follower', 'candidate', 'leader', 'shutdown'];
const VOTES = ['nobody', 'itself', 'n1', 'n2'];
const same = (a, b) => a.role === b.role && a.term === b.term && a.votedFor === b.votedFor;

export const stateInvariants = [
  { name: 'role is one of the four', pred: (s) => ROLES.includes(s.role) },
  { name: 'votedFor is one of the four', pred: (s) => VOTES.includes(s.votedFor) },
  { name: 'term is an integer in 0..3', pred: (s) => Number.isInteger(s.term) && s.term >= 0 && s.term <= 3 },
  { name: 'term 0 means follower or shutdown (no election yet)', pred: (s) => s.term > 0 || s.role === 'follower' || s.role === 'shutdown' },
  { name: 'nobody votes in term 0', pred: (s) => s.term > 0 || s.votedFor === 'nobody' },
  { name: 'a candidate or leader voted for itself', pred: (s) => (s.role !== 'candidate' && s.role !== 'leader') || s.votedFor === 'itself' },
];

export const transitionInvariants = [
  { name: 'term never goes down', pred: (pre, a, d, post) => post.term >= pre.term },
  {
    name: 'only an election or a newer term changes the term',
    pred: (pre, a, d, post) => post.term === pre.term || a === 'electionTimeout' || a === 'newerTermSeen' || a === 'voteRequested',
  },
  {
    name: 'voteRequested changes the term only to the newer requested term',
    pred: (pre, a, d, post) => a !== 'voteRequested' || post.term === pre.term || (post.term === d.term && d.term > pre.term),
  },
  {
    name: 'election moves the term up by exactly 1 into candidate, voting for itself',
    pred: (pre, a, d, post) =>
      a !== 'electionTimeout' || same(pre, post) ||
      (post.role === 'candidate' && post.term === pre.term + 1 && post.votedFor === 'itself'),
  },
  {
    name: 'a leader was a candidate first in its own term',
    pred: (pre, a, d, post) => post.role !== 'leader' || pre.role === 'leader' || (pre.role === 'candidate' && pre.term === post.term),
  },
  { name: 'a leader never times out', pred: (pre, a, d, post) => !(a === 'electionTimeout' && pre.role === 'leader') || same(pre, post) },
  { name: 'a shut down node stays shut down, unchanged', pred: (pre, a, d, post) => pre.role !== 'shutdown' || same(pre, post) },
  { name: 'shutdown keeps the term and vote', pred: (pre, a, d, post) => post.role !== 'shutdown' || (post.term === pre.term && post.votedFor === pre.votedFor) },
  {
    name: 'newerTermSeen only accepts a strictly newer term in 1..3, makes a follower that has not voted',
    pred: (pre, a, d, post) =>
      a !== 'newerTermSeen' || same(pre, post) ||
      (post.role === 'follower' && post.votedFor === 'nobody' && post.term === d.term &&
        Number.isInteger(d.term) && d.term >= 1 && d.term <= 3 && d.term > pre.term),
  },
  {
    name: 'quorumLost: leader steps down in the same term',
    pred: (pre, a, d, post) => a !== 'quorumLost' || same(pre, post) || (pre.role === 'leader' && post.role === 'follower' && post.term === pre.term),
  },
  {
    name: 'at most one vote per term',
    pred: (pre, a, d, post) => post.term !== pre.term || pre.votedFor === 'nobody' || post.votedFor === pre.votedFor,
  },
  {
    name: 'a vote changes only by voteRequested, electionTimeout or a newer term',
    pred: (pre, a, d, post) => post.votedFor === pre.votedFor || a === 'voteRequested' || a === 'electionTimeout' || a === 'newerTermSeen',
  },
  {
    name: 'a granted vote is for a valid peer in a valid term, as a follower',
    pred: (pre, a, d, post) =>
      a !== 'voteRequested' || same(pre, post) ||
      ((d.candidate === 'n1' || d.candidate === 'n2') && Number.isInteger(d.term) && d.term >= 1 && d.term <= 3 &&
        post.role === 'follower' && post.votedFor === d.candidate && post.term === d.term),
  },
  {
    name: 'in its own term, only a follower that had not voted (or voted for this candidate) grants',
    pred: (pre, a, d, post) =>
      a !== 'voteRequested' || d.term !== pre.term || same(pre, post) ||
      (pre.role === 'follower' && (pre.votedFor === 'nobody' || pre.votedFor === d.candidate)),
  },
];

// The polygraph spec (spec/node.spec.cjs) and the implementation's step() must agree
// on every (reachable state, command) pair, including the refusals.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { writeFileSync, mkdirSync } from 'node:fs';
// @ts-ignore: plain JS module from the polygraph tool
import { loadSpec } from '../tools/polygraph/scripts/load-spec.mjs';
import { INITIAL_STATE, step } from '../src/node-machine.ts';
import type { Command, NodeState } from '../src/node-machine.ts';

const spec = loadSpec('spec/node.spec.cjs');
const commands: Command[] = [
  { type: 'electionTimeout' },
  { type: 'electionWon' },
  { type: 'quorumLost' },
  { type: 'shutdown' },
  ...[-1, 0, 1, 1.5, 2, 3, 4].map((term) => ({ type: 'newerTermSeen', term }) as Command),
  ...['n1', 'n2', 'n3', 'itself', 'nobody'].flatMap((candidate) =>
    [-1, 0, 1, 1.5, 2, 3, 4].map((term) => ({ type: 'voteRequested', candidate, term }) as Command)),
];

test('spec and implementation agree on every reachable step', () => {
  const seen = new Set<string>();
  const queue: NodeState[] = [INITIAL_STATE];
  const windows: string[] = [];
  while (queue.length) {
    const s = queue.shift()!;
    const key = JSON.stringify(s);
    if (seen.has(key)) continue;
    seen.add(key);
    for (const c of commands) {
      const r = step(s, c);
      const implPost = r.ok ? r.state : s;
      spec.setState({ ...s });
      const { type, ...data } = c;
      spec.actions[type](data);
      const specPost = spec.getState();
      assert.deepEqual({ role: specPost.role, term: specPost.term, votedFor: specPost.votedFor }, implPost, `${key} ${JSON.stringify(c)}`);
      windows.push(JSON.stringify({ pre: s, action: type, data, post: implPost }));
      queue.push(implPost);
    }
  }
  assert.equal(seen.size, 32,[...seen].sort().join('\n'));
  mkdirSync('spec/traces', { recursive: true });
  writeFileSync('spec/traces/exhaustive.ndjson', windows.join('\n') + '\n');
});

