const TERMS = [-1, 0, 1, 1.5, 2, 3, 4];
const CANDIDATES = ['n1', 'n2', 'n3', 'itself', 'nobody'];

const noData = () => ({ action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] });
const validTerm = (t) => typeof t === 'number' && Number.isInteger(t) && t >= 1 && t <= MAX_TERM;

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      role: { type: 'string' },
      term: { type: 'number' },
      votedFor: { type: 'string' },
    },
    actions: {
      electionTimeout: noData(),
      electionWon: noData(),
      electionLost: noData(),
      newerTermSeen: {
        action: (data = {}) => ({ ...data }),
        schema: { term: { type: 'number', required: true } },
        domain: TERMS.map((term) => ({ term })),
      },
      quorumLost: noData(),
      shutdown: noData(),
      voteRequested: {
        action: (data = {}) => ({ ...data }),
        schema: { candidate: { type: 'string', required: true }, term: { type: 'number', required: true } },
        domain: CANDIDATES.flatMap((candidate) => TERMS.map((term) => ({ candidate, term }))),
      },
    },
    acceptors: {
      electionTimeout: (model) => (proposal, { reject, next }) => {
        if (model.role === 'shutdown') return reject('shut-down');
        if (model.role === 'leader') return reject('leader-does-not-time-out');
        if (model.term >= MAX_TERM) return reject('no-term-after-max');
