        next.role = 'leader';
        unchanged('term', 'votedFor');
      },
      electionLost: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('shut-down');
        if (model.role !== 'candidate') return reject('not-candidate');
        next.role = 'follower';
        unchanged('term', 'votedFor');
      },
      newerTermSeen: (model) => (proposal, { reject, next }) => {
        if (model.role === 'shutdown') return reject('shut-down');
