rep("votedFor: 'nobody' };","votedFor: 'nobody', paused: false };\n// paused: a paused follower starts no election");
rep("      votedFor: { type: 'string' },\n","      votedFor: { type: 'string' },\n      paused: { type: 'boolean' },\n");
rep("      shutdown: noData(),\n","      shutdown: noData(),\n      pause: noData(),\n      resume: noData(),\n");
rep("        if (model.role === 'leader') return reject('leader-does-not-time-out');\n","        if (model.role === 'leader') return reject('leader-does-not-time-out');\n        if (model.paused) return reject('paused');\n");
rep("        next.votedFor = 'itself';\n","        next.votedFor = 'itself';\n        unchanged('paused');\n");
rep("unchanged('term', 'votedFor');","unchanged('term', 'votedFor', 'paused');");
rep("        next.votedFor = 'nobody';\n","        next.votedFor = 'nobody';\n        unchanged('paused');\n");
rep("          next.votedFor = candidate;\n          return;","          next.votedFor = candidate;\n          unchanged('paused');\n          return;");
rep("unchanged('role', 'term');","unchanged('role', 'term', 'paused');");
rep(`      voteRequested: (model) =>`,`      pause: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('shut-down');
        if (model.role !== 'follower') return reject('not-follower');
        if (model.paused) return reject('already-paused');
        next.paused = true;
        unchanged('role', 'term', 'votedFor');
      },
      resume: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('shut-down');
        if (!model.paused) return reject('not-paused');
        next.paused = false;
        unchanged('role', 'term', 'votedFor');
      },
      voteRequested: (model) =>`);
rep("  shutdown: (data = {}) => intents.shutdown(data),\n","  shutdown: (data = {}) => intents.shutdown(data),\n  pause: (data = {}) => intents.pause(data),\n  resume: (data = {}) => intents.resume(data),\n");
